BEGIN;
ALTER TABLE "EconomyAccount" ADD CONSTRAINT "EconomyAccount_balances_nonnegative" CHECK ("wallet" >= 0 AND "bank" >= 0);
CREATE UNIQUE INDEX "ToolInstance_one_equipped_per_slot" ON "ToolInstance"("guildId","userId","slot") WHERE "equipped" = true;
ALTER TABLE "InventoryEntry" ADD COLUMN "acquiredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE "InventoryEntry" ADD CONSTRAINT "InventoryEntry_quantity_nonnegative" CHECK ("quantity" >= 0);
ALTER TABLE "ToolInstance" ADD COLUMN "locked" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "ToolInstance" ADD CONSTRAINT "ToolInstance_durability_bounds" CHECK ("maxDurability" > 0 AND "durability" >= 0 AND "durability" <= "maxDurability");
ALTER TABLE "CraftedChair" ADD COLUMN "locked" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE "OperationReceipt" ("guildId" TEXT NOT NULL, "key" TEXT NOT NULL, "fingerprint" TEXT NOT NULL, "result" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("guildId","key"));
CREATE TABLE "InventoryCategoryLock" ("guildId" TEXT NOT NULL,"userId" TEXT NOT NULL,"category" TEXT NOT NULL,PRIMARY KEY("guildId","userId","category"));
CREATE TABLE "CollectionSet" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"hidden" BOOLEAN NOT NULL DEFAULT false,"itemIds" TEXT[] NOT NULL,"badgeId" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "CollectionDiscovery" ("guildId" TEXT NOT NULL,"userId" TEXT NOT NULL,"itemId" TEXT NOT NULL,"foundAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("guildId","userId","itemId"));
CREATE TABLE "GiftRecord" ("id" TEXT PRIMARY KEY,"guildId" TEXT NOT NULL,"senderId" TEXT NOT NULL,"recipientId" TEXT NOT NULL,"itemId" TEXT NOT NULL,"quantity" INTEGER NOT NULL CHECK("quantity">0),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "GiftRecord_guildId_senderId_idx" ON "GiftRecord"("guildId","senderId");
CREATE INDEX "GiftRecord_guildId_recipientId_idx" ON "GiftRecord"("guildId","recipientId");

-- Phase 09 seed/default content; live catalog remains PostgreSQL-backed.

COMMIT;
